#include <stdint.h>
#include <stddef.h>
extern uintptr_t Тақта_нүкте(uintptr_t,uintptr_t,uintptr_t),Тақта_Терминал(uintptr_t);
extern void Терминал_глиф(unsigned,unsigned,unsigned,unsigned,unsigned);
extern void *memset(void *,int,size_t);
typedef struct { int Санат_мән,басты,x_координатасы,Y_түймешігі_координата,너비값,높이값,보이는지,қолдан_макет,макет_саясат;unsigned Мәтін[128],ұзындық_мән; } виджет_күй;
static виджет_күй 요소들[4][32];
static int Cұрыпталған[4],оқиға_Тізім[4][16];static unsigned 첫항목[4],항목수[4],부호없는결과[4],긴부호없는값[4];
static void Оқиға(int ие_нысан,int мән){if(항목수[ие_нысан]<16){оқиға_Тізім[ие_нысан][(첫항목[ие_нысан]+항목수[ие_нысан])%16]=мән;항목수[ие_нысан]++;}}
static виджет_күй *элемент_мән(int ие_нысан,int идентификатор_мән){return ие_нысан>=0&&ие_нысан<4&&идентификатор_мән>0&&идентификатор_мән<=32&&요소들[ие_нысан][идентификатор_мән-1].Санат_мән?&요소들[ие_нысан][идентификатор_мән-1]:0;}
static void 사각영역(int x_координатасы,int Y_түймешігі_координата,int 너비값,int 높이값,unsigned 색상){Тақта_тік_төртбұрыш_бояу(x_координатасы,Y_түймешігі_координата,너비값,높이값,색상);}
int 화면보임(int ие_нысан){if(ие_нысан<0||ие_нысан>=4)return 0;for(int 순번=0;순번<32;순번++)if(요소들[ие_нысан][순번].Санат_мән==1&&요소들[ие_нысан][순번].보이는지)return 1;return 0;}
void 화면초기화(int ие_нысан){memset(요소들[ие_нысан],0,sizeof(요소들[ие_нысан]));항목수[ие_нысан]=첫항목[ие_нысан]=Cұрыпталған[ие_нысан]=긴부호없는값[ие_нысан]=0;}
static void Орны(int ие_нысан,виджет_күй *너비값,int *x_координатасы,int *Y_түймешігі_координата){*x_координатасы=너비값->x_координатасы;*Y_түймешігі_координата=너비값->Y_түймешігі_координата;int деректер_лауазым=너비값->басты;for(int 개수=0;деректер_лауазым&&개수<32;개수++){виджет_күй *위쪽=элемент_мән(ие_нысан,деректер_лауазым);if(!위쪽)break;*x_координатасы+=위쪽->x_координатасы;*Y_түймешігі_координата+=위쪽->Y_түймешігі_координата+(위쪽->Санат_мән==1?30:0);деректер_лауазым=위쪽->басты;}}
static int 표시됨(int ие_нысан,виджет_күй *너비값){for(int 개수=0;개수<32;개수++){if(!너비값->보이는지)return 0;if(너비값->Санат_мән==1)return 1;너비값=элемент_мән(ие_нысан,너비값->басты);if(!너비값)return 0;}return 0;}
static void Мәтін(int x_координатасы,int Y_түймешігі_координата,виджет_күй *너비값,int 최대값,unsigned 색상,unsigned 배경색){int ток_лауазым=0;for(unsigned 순번=0;순번<너비값->ұзындық_мән;순번++){unsigned символдарды_кодтау=너비값->Мәтін[순번],너비=символдарды_кодтау>=256?16:8;if(ток_лауазым+(int)너비>최대값)break;Терминал_глиф(x_координатасы+ток_лауазым,Y_түймешігі_координата,символдарды_кодтау,색상,배경색);ток_лауазым+=너비;}}
void 화면다시그림(int ие_нысан){
    if(!화면보임(ие_нысан))return;
    for(int өңдеу_рет=1;өңдеу_рет<=5;өңдеу_рет++)for(int 순번=0;순번<32;순번++){
        виджет_күй *너비값=&요소들[ие_нысан][순번];if(너비값->Санат_мән!=өңдеу_рет||!표시됨(ие_нысан,너비값))continue;int x_координатасы,Y_түймешігі_координата;Орны(ие_нысан,너비값,&x_координатасы,&Y_түймешігі_координата);
        if(өңдеу_рет==1){사각영역(x_координатасы,Y_түймешігі_координата,너비값->너비값,너비값->높이값,0xeee9e0);사각영역(x_координатасы,Y_түймешігі_координата,너비값->너비값,30,0x905020);Мәтін(x_координатасы+10,Y_түймешігі_координата+7,너비값,너비값->너비값-50,0xffffff,0x905020);사각영역(x_координатасы+너비값->너비값-28,Y_түймешігі_координата+4,24,22,0x5555b8);Терминал_глиф(x_координатасы+너비값->너비값-20,Y_түймешігі_координата+7,'X',0xffffff,0x5555b8);}
        if(өңдеу_рет==2)사각영역(x_координатасы,Y_түймешігі_координата,너비값->너비값,너비값->높이값,0xeee9e0);
        if(өңдеу_рет>=3){unsigned 배경색=өңдеу_рет==4?0xc0ab86:өңдеу_рет==5?0xffffff:0xeee9e0;if(өңдеу_рет!=3)사각영역(x_координатасы,Y_түймешігі_координата,너비값->너비값,너비값->높이값,배경색);Мәтін(x_координатасы+4,Y_түймешігі_координата+4,너비값,너비값->너비값-8,0x201a15,배경색);if(өңдеу_рет==5&&Cұрыпталған[ие_нысан]==순번+1)사각영역(x_координатасы,Y_түймешігі_координата+너비값->높이값-2,너비값->너비값,2,0x905020);}
    }
}
int 화면덮음(int ие_нысан,int x_координатасы,int Y_түймешігі_координата){
    if(!화면보임(ие_нысан))return 0;
    for(int 순번=0;순번<32;순번++){
        виджет_күй *Терезе=&요소들[ие_нысан][순번];
        if(Терезе->Санат_мән==1&&Терезе->보이는지&&x_координатасы>=Терезе->x_координатасы&&Y_түймешігі_координата>=Терезе->Y_түймешігі_координата&&
           x_координатасы<Терезе->x_координатасы+Терезе->너비값&&Y_түймешігі_координата<Терезе->Y_түймешігі_координата+Терезе->높이값)return 1;
    }return 0;
}
int 화면가리킴(int ие_нысан,unsigned 눌림,int x_координатасы,int Y_түймешігі_координата){
    if(!화면보임(ие_нысан))return 0;
    if(눌림&1)for(int 순번=31;순번>=0;순번--){виджет_күй *너비값=&요소들[ие_нысан][순번];if(!너비값->Санат_мән||!표시됨(ие_нысан,너비값))continue;int терезе_X_түймешігі,терезе_Y_түймешігі;Орны(ие_нысан,너비값,&терезе_X_түймешігі,&терезе_Y_түймешігі);
        if(x_координатасы<терезе_X_түймешігі||Y_түймешігі_координата<терезе_Y_түймешігі||x_координатасы>=терезе_X_түймешігі+너비값->너비값||Y_түймешігі_координата>=терезе_Y_түймешігі+너비값->높이값)continue;
        if(너비값->Санат_мән==1&&Y_түймешігі_координата<терезе_Y_түймешігі+30&&x_координатасы>=терезе_X_түймешігі+너비값->너비값-28){if(너비값->макет_саясат!=0)너비값->보이는지=0;Оқиға(ие_нысан,0x10000+순번+1);Тақта_Терминал(3);return 1;}
        if(너비값->Санат_мән==4){Оқиға(ие_нысан,순번+1);return 1;}if(너비값->Санат_мән==5){Cұрыпталған[ие_нысан]=순번+1;Тақта_Терминал(3);return 1;}
        if(너비값->Санат_мән==1)return 1;
    }return 0;
}
void 화면누름(int ие_нысан,unsigned 둘째값){
    виджет_күй *너비값=элемент_мән(ие_нысан,Cұрыпталған[ие_нысан]);if(!너비값||너비값->Санат_мән!=5)return;
    if(둘째값==13||둘째값==10){Оқиға(ие_нысан,Cұрыпталған[ие_нысан]);return;}
    if(둘째값==8||둘째값==127){if(너비값->ұзындық_мән)너비값->ұзындық_мән--;긴부호없는값[ие_нысан]=0;}
    else{
        unsigned символдарды_кодтау=둘째값;
        if(긴부호없는값[ие_нысан]){if((둘째값&192)!=128){긴부호없는값[ие_нысан]=0;return;}부호없는결과[ие_нысан]=(부호없는결과[ие_нысан]<<6)|(둘째값&63);if(--긴부호없는값[ие_нысан])return;символдарды_кодтау=부호없는결과[ие_нысан];}
        else if(둘째값>=0xc2&&둘째값<=0xf4){긴부호없는값[ие_нысан]=둘째값<0xe0?1:둘째값<0xf0?2:3;부호없는결과[ие_нысан]=둘째값&((1u<<(6-긴부호없는값[ие_нысан]))-1);return;}
        else if(둘째값<32||둘째값>=128)return;
        if(символдарды_кодтау>0x10ffff||(символдарды_кодтау>=0xd800&&символдарды_кодтау<=0xdfff))return;if(너비값->ұзындық_мән<127)너비값->Мәтін[너비값->ұзындық_мән++]=символдарды_кодтау;
    }
    Тақта_Терминал(3);
}
int 화면호출(int ие_нысан,unsigned Әрекет,int идентификатор_мән,int 첫째값,int 둘째값,int таңба_коды,int тағайындау_деректер){
    if(ие_нысан<0||ие_нысан>=4)return -22;виджет_күй *너비값=элемент_мән(ие_нысан,идентификатор_мән);
    if(Әрекет==0){if(идентификатор_мән<1||идентификатор_мән>5)return -22;for(int 순번=0;순번<32;순번++)if(요소들[ие_нысан][순번].Санат_мән==0){너비값=&요소들[ие_нысан][순번];memset(너비값,0,sizeof(*너비값));너비값->Санат_мән=идентификатор_мән;너비값->보이는지=идентификатор_мән!=1;너비값->너비값=идентификатор_мән==1?380:220;너비값->높이값=идентификатор_мән==1?240:28;너비값->макет_саясат=1;너비값->x_координатасы=идентификатор_мән==1?130:16;너비값->Y_түймешігі_координата=идентификатор_мән==1?110:16;return 순번+1;}return -28;}
    if(Әрекет==5){if(!항목수[ие_нысан])return 0;int 반환값=оқиға_Тізім[ие_нысан][첫항목[ие_нысан]];첫항목[ие_нысан]=(첫항목[ие_нысан]+1)%16;항목수[ие_нысан]--;return 반환값;}
    if(Әрекет==6)return 화면보임(ие_нысан);
    if(!너비값)return -9;
    int 이전표시=표시됨(ие_нысан,너비값);
    if(Әрекет==1){int 바탕너비=보드화면너비(),바탕높이=보드화면높이();if(첫째값<0||둘째값<0||таңба_коды<1||тағайындау_деректер<1||첫째값>바탕너비||둘째값>바탕높이||таңба_коды>바탕너비-첫째값||тағайындау_деректер>바탕높이-둘째값)return -22;너비값->x_координатасы=첫째값;너비값->Y_түймешігі_координата=둘째값;너비값->너비값=таңба_коды;너비값->높이값=тағайындау_деректер;너비값->қолдан_макет=1;}
    else if(Әрекет==2){виджет_күй *еншілес_элемент=элемент_мән(ие_нысан,첫째값);if(!еншілес_элемент||еншілес_элемент==너비값||еншілес_элемент->Санат_мән==1)return -22;int деректер_лауазым=идентификатор_мән;for(int 깊이=0;деректер_лауазым&&깊이<32;깊이++){if(деректер_лауазым==첫째값)return -22;виджет_күй *위쪽=элемент_мән(ие_нысан,деректер_лауазым);деректер_лауазым=위쪽?위쪽->басты:0;}еншілес_элемент->басты=идентификатор_мән;if(!еншілес_элемент->қолдан_макет){int 형제요소=0;for(int 순번=0;순번<32;순번++)if(&요소들[ие_нысан][순번]!=еншілес_элемент&&요소들[ие_нысан][순번].басты==идентификатор_мән)형제요소++;еншілес_элемент->Y_түймешігі_координата=16+형제요소*36;}}
    else if(Әрекет==3)너비값->보이는지=첫째값!=0;
    else if(Әрекет==4)너비값->보이는지=0;
    else if(Әрекет==7)너비값->макет_саясат=첫째값;
    else if(Әрекет==8)return 너비값->ұзындық_мән;
    else if(Әрекет==9)return 첫째값>=0&&(unsigned)첫째값<너비값->ұзындық_мән?너비값->Мәтін[첫째값]:-22;
    else return -22;
    if(이전표시||표시됨(ие_нысан,너비값))Тақта_Терминал(3);return 0;
}
int 화면글(int ие_нысан,int идентификатор_мән,const uint32_t *деректер,unsigned 개수){виджет_күй *너비값=элемент_мән(ие_нысан,идентификатор_мән);if(!너비값)return -9;if(개수>127)return -22;for(unsigned 순번=0;순번<개수;순번++){unsigned символдарды_кодтау=деректер[순번];if(символдарды_кодтау>0x10ffff||(символдарды_кодтау>=0xd800&&символдарды_кодтау<=0xdfff))return -22;}for(unsigned 순번=0;순번<개수;순번++)너비값->Мәтін[순번]=деректер[순번];너비값->ұзындық_мән=개수;if(표시됨(ие_нысан,너비값))Тақта_Терминал(3);return 0;}
